local fabric={}local wm local storage local labels={}local greeted={}local pending={}local nonce=0 function fabric.present()return type(cee)=="table"and type(cee.fabricPeers)=="function"and type(cee.fabricSend)=="function"end local function selfId()if type(os.getComputerID)~="function"then return nil end local ok,v=pcall(os.getComputerID)if ok and type(v)=="number"then return v end return nil end local function ourLabel()if type(os.getComputerLabel)=="function"then local ok,v=pcall(os.getComputerLabel)if ok and type(v)=="string"and v~=""then return v end end return"Computer "..tostring(selfId()or"?")end function fabric.peerName(id)if labels[id]then return labels[id]end return"Computer "..tostring(id)end function fabric.peers()local out={}if not fabric.present()then return out end local ok,raw=pcall(cee.fabricPeers)if not ok or type(raw)~="table"then return out end local me=selfId()local function take(p,keyed)if type(p)~="table"then return end local id=p.id or keyed if type(id)~="number"or id==me then return end if(p.kind or"computer")~="computer"then return end out[#out+1]={id=id,kind="computer",label=labels[id]}end if raw.id~=nil or raw.kind~=nil then take(raw,nil)elseif#raw>0 then for i=1,#raw do take(raw[i],nil)end else for k,p in pairs(raw)do take(p,tonumber(k))end end table.sort(out,function(a,b)return a.id<b.id end)return out end function fabric.send(id,msg)if not fabric.present()or type(id)~="number"or msg==nil then return false end local ok,sent=pcall(cee.fabricSend,id,msg)if not ok then return false end return sent~=false end function fabric.runOn(id,path,cb)local function answer(ok,msg)if cb then cb(ok,msg)end return false end if not fabric.present()then return answer(false,"the fabric link is not available")end if type(path)~="string"or not fs.exists(path)or fs.isDir(path)then return answer(false,"not a program: "..tostring(path))end local f=fs.open(path,"r")if not f then return answer(false,"cannot read "..path)end local src=f.readAll()f.close()nonce=nonce+1 local mine=nonce if cb then pending[mine]=cb end local sent=fabric.send(id,{op="run",id=mine,path=path,name=fs.getName(path),source=type(src)=="string"and src or"",})if not sent then pending[mine]=nil return answer(false,"could not reach "..fabric.peerName(id))end return true end local function note(id,label)if type(id)~="number"then return end greeted[id]=true if type(label)=="string"and label~=""then labels[id]=label end end local function safeName(name)local n=tostring(name or""):match("[^/\\]+$")or""n=n:gsub("[^%w%._%-]","_")if n==""or n=="."or n==".."then n="program.lua"end return n end local function handleRun(p,sender)local name=safeName(p.name or(type(p.path)=="string"and fs.getName(p.path)))local target,why if type(p.path)=="string"and p.path~=""and fs.exists(p.path)and not fs.isDir(p.path)then target=p.path elseif type(p.source)=="string"then target=fs.combine("/received",name)pcall(fs.makeDir,"/received")local ok,why if storage then ok,why=storage.write(target,p.source,{backup=false})else local f=fs.open(target,"w")if f then local wrote,err=pcall(f.write,p.source)local closed,closeErr=pcall(f.close)ok=wrote and closed why=err or closeErr else ok,why=false,"cannot open"end end if not ok then target,why=nil,"cannot write "..target..(why and(" ("..tostring(why)..")")or"")end end if not target then fabric.send(sender,{op="result",id=p.id,ok=false,message=why or("not found: "..tostring(p.path)),})return end local started=false if wm then local ok,created=pcall(wm.create,"console",{program=target})started=ok and created~=nil if not started then why=tostring(created or"cannot open a console")if storage then storage.append("/ccwin/last-error.log","[fabric] "..why:gsub("[\r\n]+"," ").."\n",storage.LOG_MAX)end end end fabric.send(sender,{op="result",id=p.id,ok=started,message=started and("running "..name)or(why or"no console to run it in"),})end function fabric.receive(payload,sender)if type(payload)~="table"or type(payload.op)~="string"then return false end local op=payload.op if op=="hello"then note(sender,payload.label)fabric.send(sender,{op="hello_reply",label=ourLabel()})return true elseif op=="hello_reply"then note(sender,payload.label)return true elseif op=="run"then handleRun(payload,sender)return true elseif op=="result"then local cb=pending[payload.id]if cb then pending[payload.id]=nil cb(payload.ok==true,payload.message)end return true end return false end function fabric.poll()if not fabric.present()then return end local seen={}for _,p in ipairs(fabric.peers())do seen[p.id]=true if not greeted[p.id]then greeted[p.id]=true fabric.send(p.id,{op="hello",label=ourLabel()})end end for id in pairs(greeted)do if not seen[id]then greeted[id]=nil end end end function fabric.attach(d)wm=d and d.wm or nil storage=d and d.storage or nil end return fabric